import os

# Look for any .jpg, .png files recursively
def find_image_files(root_dir='.'):
    image_files = []
    for root, dirs, files in os.walk(root_dir):
        for file in files:
            if file.lower().endswith(('.jpg', '.jpeg', '.png', '.bmp', '.gif')):
                full_path = os.path.join(root, file)
                # Check if it's a real image file by checking size and header
                try:
                    file_size = os.path.getsize(full_path)
                    if file_size > 1000:  # Skip very small files (likely not real images)
                        with open(full_path, 'rb') as f:
                            header = f.read(4)
                            # Check for common image magic numbers
                            if header[:2] in [b'\xff\xd8', b'\x89PNG', b'BM', b'GIF']:
                                image_files.append(full_path)
                except:
                    pass
    return image_files

print("Searching for image files...")
images = find_image_files()
print(f"Found {len(images)} potential image files")
if images:
    print("First 10:", images[:10])"}

